      ret.should.eql(true);

      ret = yield cache.get('h', cache.CONSTANT.FORCEMASTER);
      console.log('9_43 ret', ret);
      ret.should.eql('1');

      ret = yield cache.setChanged('h', '1');
      console.log('9_44 ret', ret);
      ret.should.eql(true);

      ret = yield cache.get('h', cache.CONSTANT.FORCEMASTER);
      console.log('9_45 ret', ret);
      ret.should.eql('1');

      ret = yield cache.setChanged('h', fixed_object);
      console.log('9_46 ret', ret);
      ret.should.eql(true);

      ret = yield cache.get('h', cache.CONSTANT.FORCEMASTER);
